mapper.select:
SELECT r.RECONCILIATION_ID, r.MODEL_ID, r.PERIOD, r.COMPANY_A_ID, r.COMPANY_A_NAME, r.COMPANY_B_ID, r.COMPANY_B_NAME, r.TRANSACTION_TYPE, r.AMOUNT_A, r.AMOUNT_B, r.DIFF_AMOUNT, r.ACCOUNT_CODE, r.ACCOUNT_NAME, r.DESCRIPTION, r.STATUS, r.TENANT_ID, r.CREATE_USER, r.CREATE_TIME, r.UPDATE_USER, r.UPDATE_TIME, m.MODEL_NAME FROM TBL_RECONCILIATION_DATA r LEFT JOIN TBL_CONSOLIDATION_MODEL m ON r.MODEL_ID = m.MODEL_ID
AND r.MODEL_ID = #{param.modelId}
AND r.PERIOD = #{param.period}
AND r.COMPANY_A_ID = #{param.companyAId}
AND r.COMPANY_A_NAME LIKE CONCAT('%', #{param.companyAName}, '%')
AND r.COMPANY_B_ID = #{param.companyBId}
AND r.COMPANY_B_NAME LIKE CONCAT('%', #{param.companyBName}, '%')
AND r.TRANSACTION_TYPE = #{param.transactionType}
AND r.STATUS = #{param.status}
ORDER BY r.CREATE_TIME DESC

mapper.delete:
DELETE FROM TBL_RECONCILIATION_DATA
WHERE MODEL_ID = #{modelId}
AND PERIOD = #{period}
